repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('united', 17), ('city', 14), ('city', 48), ('rovers', 7), ('united', 24)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

repo.steps.py:
"""Changes in goals from one fixture to the next."""


def goals_changes(fixtures):
    """Return the change in goals from each fixture to the next: one entry for every neighbouring pair."""
    out = []
    for i in range(2, len(fixtures)):
        out.append(fixtures[i].goals - fixtures[i - 1].goals)
    return out


def biggest_rise(fixtures):
    """Return the largest increase between neighbours, or 0 when there is none."""
    rises = [c for c in goals_changes(fixtures) if c > 0]
    return max(rises) if rises else 0


def club_names(fixtures):
    """Return the distinct club values, in first-seen order."""
    names = []
    for x in fixtures:
        if x.club not in names:
            names.append(x.club)
    return names


def largest_goals(fixtures):
    """Return the largest goals, or None when there are no fixtures."""
    values = [x.goals for x in fixtures]
    return max(values) if values else None

