from fixtures import load_fixtures, ROWS
from steps import goals_changes


def test_number_of_changes():
    assert len(goals_changes(list(load_fixtures()))) == len(ROWS) - 1


def test_single_item():
    assert goals_changes(list(load_fixtures())[:1]) == []
